/**
 * Structural labs — the six explorable models.
 *
 * SOURCE OF TRUTH
 *   The models themselves live in 18-architecture-models and follow the
 *   unified model contract (v1.1). They are vendored under ./lab/models/ and
 *   ./lab/core/ and are loaded **on demand** — the Three.js engine never
 *   touches the first screen.
 *
 *   ./lab/../data/labs-meta.js is the static extract of those models
 *   (generated by scripts/gen-labs-meta.mjs): titles, layers, component
 *   names and roles, load path, assembly steps, force arrows. It exists so
 *   this module can be imported by the first screen without pulling in
 *   Three.js.
 *
 * TEACHING SCHEMATIC
 *   Every model carries 18's own standing notice: the geometry explains how
 *   a member works. It is not a measured survey and not an engineering model.
 *   Force arrows are a QUALITATIVE description of the load path, never a
 *   structural calculation.
 */

import { LABS_META } from './labs-meta.js';

